    /**
     * Seed the application's database.
     */
    public function run(): void
    {
        $banks = [
            'Неловкие и ловкие ситуации' => self::AWKWARD_QUESTIONS,
            'Абсурдные ситуации' => self::ABSURD_QUESTIONS,
            'Жизненные ситуации' => self::LIFE_QUESTIONS,
            'Дикая природа и изоляция' => self::WILDERNESS_QUESTIONS,
            'Цифровой след и интернет-культура' => self::DIGITAL_QUESTIONS,
        ];

        foreach ($banks as $bankName => $questions) {
            $bank = QuestionBank::updateOrCreate(['name' => $bankName]);

            foreach ($questions as $question) {
                Question::firstOrCreate([
                    'question_bank_id' => $bank->id,
                    'situation' => $question['situation'],
                ], [
                    'reward_sparks' => $question['reward_sparks'],
                ]);
            }
        }
    }
